import { MakeLogicType, connect, kea, key, listeners, path, props } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'
import { ErrorTrackingSpikeEvent } from 'lib/components/Errors/types'

import { DateRange, ErrorTrackingIssue } from '~/queries/schema/schema-general'

import {
    ERROR_TRACKING_ISSUE_SCENE_LOGIC_KEY,
    issueFiltersLogic,
} from '../../components/IssueFilters/issueFiltersLogic'
import { dateRangeToIsoBounds } from '../../utils'

export interface IssueSpikeEventsLogicProps {
    issueId: ErrorTrackingIssue['id']
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueSpikeEventsLogicValues {
    dateRange: DateRange // issueFiltersLogic
    spikeEvents: ErrorTrackingSpikeEvent[]
    spikeEventsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueSpikeEventsLogicActions {
    setDateRange: (
        dateRange: DateRange,
        fromPreview?: boolean | undefined
    ) => {
        dateRange: DateRange
        fromPreview: boolean
    } // issueFiltersLogic
    loadSpikeEvents: () => any
    loadSpikeEventsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSpikeEventsSuccess: (
        spikeEvents: ErrorTrackingSpikeEvent[],
        payload?: any
    ) => {
        spikeEvents: ErrorTrackingSpikeEvent[]
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueSpikeEventsLogicMeta {
    key: string
}

export type issueSpikeEventsLogicType = MakeLogicType<
    issueSpikeEventsLogicValues,
    issueSpikeEventsLogicActions,
    IssueSpikeEventsLogicProps,
    issueSpikeEventsLogicMeta
>

export const issueSpikeEventsLogic = kea<issueSpikeEventsLogicType>([
    props({} as IssueSpikeEventsLogicProps),
    key((props) => props.issueId),
    path((key) => ['products', 'error_tracking', 'scenes', 'ErrorTrackingIssueScene', 'issueSpikeEventsLogic', key]),

    connect(() => ({
        values: [issueFiltersLogic({ logicKey: ERROR_TRACKING_ISSUE_SCENE_LOGIC_KEY }), ['dateRange']],
        actions: [issueFiltersLogic({ logicKey: ERROR_TRACKING_ISSUE_SCENE_LOGIC_KEY }), ['setDateRange']],
    })),

    loaders(({ values, props }) => ({
        spikeEvents: [
            [] as ErrorTrackingSpikeEvent[],
            {
                loadSpikeEvents: async () => {
                    const { dateFrom, dateTo } = dateRangeToIsoBounds(values.dateRange)
                    // nosemgrep: prefer-codegen-api-namespaced-error_tracking -- hogli product:maturity tracks this call for the move to the generated client
                    const response = await api.errorTracking.getSpikeEvents({
                        issueIds: [props.issueId],
                        dateFrom,
                        dateTo,
                    })
                    return response.results
                },
            },
        ],
    })),

    listeners(({ actions }) => ({
        setDateRange: () => actions.loadSpikeEvents(),
    })),
])
